/** A `Identity` (an input struct). */
export interface Identity {
  /** `Text`: at most 31 UTF-8 bytes. */
  document: string;
  /** A calendar day: the `Date`'s UTC day, as `toISOString()` shows it (`new Date("1990-01-01")`). */
  born: Date;
  /** One `Country`, or a list of them. */
  nationality: Country | readonly Country[];
  /** `u64`: an integer in [0, 2^64). */
  netWorth: bigint | number;
  /** A calendar day: the `Date`'s UTC day, as `toISOString()` shows it (`new Date("1990-01-01")`). */
  expires: Date;
  salt: FieldLike;
}

/** Every input of `zk_kyc`. */
export interface ZkKycInputs {
  id: Identity;
  commitment: FieldLike;
  /** A calendar day: the `Date`'s UTC day, as `toISOString()` shows it (`new Date("1990-01-01")`). */
  bornBefore: Date;
  /** `u64`: an integer in [0, 2^64). */
  minNetWorth: bigint | number;
  /** A calendar day: the `Date`'s UTC day, as `toISOString()` shows it (`new Date("1990-01-01")`). */
  today: Date;
  /** One `Country`, or a list of them. */
  allowed: Country | readonly Country[];
}

/** The public inputs: what a verifier supplies, and what a proof reveals. */
export interface ZkKycPublicInputs {
  commitment: FieldLike;
  /** A calendar day: the `Date`'s UTC day, as `toISOString()` shows it (`new Date("1990-01-01")`). */
  bornBefore: Date;
  /** `u64`: an integer in [0, 2^64). */
  minNetWorth: bigint | number;
  /** A calendar day: the `Date`'s UTC day, as `toISOString()` shows it (`new Date("1990-01-01")`). */
  today: Date;
  /** One `Country`, or a list of them. */
  allowed: Country | readonly Country[];
}

/** The public inputs, decoded from a proof. */
export interface ZkKycPublicValues {
  commitment: bigint;
  bornBefore: Date;
  minNetWorth: bigint;
  today: Date;
  allowed: Country[];
}

/** The parts of `@blueshift-gg/xark-wasm` this client uses (any of its builds). */
export interface XarkWasm {
  prove(circuit: Uint8Array, provingKey: Uint8Array, inputs: Record<string, string>): { proof: Uint8Array; publicInputs: Uint8Array };
  verify(verifyingKey: Uint8Array, proof: Uint8Array, publicInputs: Uint8Array): boolean;
  encodeInputs(schema: string, inputs: string): Record<string, string>;
  encodePublicInputs(schema: string, publicInputs: string): Uint8Array;
  decodePublicValues(schema: string, publicInputs: Uint8Array): string;
}

/** A proof, with its public inputs decoded and as the bytes `verify` takes. */
export interface ZkKycProof {
  proof: Uint8Array;
  publicInputs: ZkKycPublicValues;
  publicInputBytes: Uint8Array;
}

/**
 * Prove and verify `zk_kyc` with the xark-wasm module you pass in:
 *
 * ```ts
 * import * as wasm from "@blueshift-gg/xark-wasm"; // node, web (after `await init()`), or bundler
 * const circuit = new ZkKyc(wasm, { circuit: xbc, provingKey: pk, verifyingKey: vk });
 * const { proof, publicInputs } = circuit.prove(inputs);
 * circuit.verify(proof, publicInputs); // true
 * ```
 */
export class ZkKyc {
  /** The circuit's `schema.json`. */
  static readonly schema = "{\"circuit\":\"zk_kyc\",\"inputs\":[{\"name\":\"id\",\"type\":{\"ref\":\"Identity\"},\"visibility\":\"private\"},{\"name\":\"commitment\",\"type\":\"field\",\"visibility\":\"public\"},{\"name\":\"born_before\",\"type\":{\"ref\":\"Date\"},\"visibility\":\"public\"},{\"name\":\"min_net_worth\",\"type\":{\"uint\":64},\"visibility\":\"public\"},{\"name\":\"today\",\"type\":{\"ref\":\"Date\"},\"visibility\":\"public\"},{\"name\":\"allowed\",\"type\":{\"ref\":\"Bitfield<Country>\"},\"visibility\":\"public\"}],\"public_inputs\":[\"commitment\",\"born_before\",\"min_net_worth\",\"today\",\"allowed\"],\"types\":{\"Bitfield<Country>\":{\"encoding\":{\"flags\":\"Country\",\"names\":\"AD,AE,AF,AG,AI,AL,AM,AO,AQ,AR,AS,AT,AU,AW,AX,AZ,BA,BB,BD,BE,BF,BG,BH,BI,BJ,BL,BM,BN,BO,BQ,BR,BS,BT,BV,BW,BY,BZ,CA,CC,CD,CF,CG,CH,CI,CK,CL,CM,CN,CO,CR,CU,CV,CW,CX,CY,CZ,DE,DJ,DK,DM,DO,DZ,EC,EE,EG,EH,ER,ES,ET,FI,FJ,FK,FM,FO,FR,GA,GB,GD,GE,GF,GG,GH,GI,GL,GM,GN,GP,GQ,GR,GS,GT,GU,GW,GY,HK,HM,HN,HR,HT,HU,ID,IE,IL,IM,IN,IO,IQ,IR,IS,IT,JE,JM,JO,JP,KE,KG,KH,KI,KM,KN,KP,KR,KW,KY,KZ,LA,LB,LC,LI,LK,LR,LS,LT,LU,LV,LY,MA,MC,MD,ME,MF,MG,MH,MK,ML,MM,MN,MO,MP,MQ,MR,MS,MT,MU,MV,MW,MX,MY,MZ,NA,NC,NE,NF,NG,NI,NL,NO,NP,NR,NU,NZ,OM,PA,PE,PF,PG,PH,PK,PL,PM,PN,PR,PS,PT,PW,PY,QA,RE,RO,RS,RU,RW,SA,SB,SC,SD,SE,SG,SH,SI,SJ,SK,SL,SM,SN,SO,SR,SS,ST,SV,SX,SY,SZ,TC,TD,TF,TG,TH,TJ,TK,TL,TM,TN,TO,TR,TT,TV,TW,TZ,UA,UG,UM,US,UY,UZ,VA,VC,VE,VG,VI,VN,VU,WF,WS,YE,YT,ZA,ZM,ZW,\"},\"newtype\":\"field\"},\"Date\":{\"encoding\":{\"date\":\"yyyymmdd\"},\"newtype\":\"field\"},\"Identity\":{\"struct\":[{\"name\":\"document\",\"type\":{\"ref\":\"Text\"}},{\"name\":\"born\",\"type\":{\"ref\":\"Date\"}},{\"name\":\"nationality\",\"type\":{\"ref\":\"Bitfield<Country>\"}},{\"name\":\"net_worth\",\"type\":{\"uint\":64}},{\"name\":\"expires\",\"type\":{\"ref\":\"Date\"}},{\"name\":\"salt\",\"type\":\"field\"}]},\"Text\":{\"encoding\":{\"text\":31},\"newtype\":\"field\"}},\"version\":1}";

  constructor(
    private readonly wasm: XarkWasm,
    private readonly keys: { circuit?: Uint8Array; provingKey?: Uint8Array; verifyingKey?: Uint8Array },
  ) {}

  /** Prove `inputs`. Throws if they don't satisfy the circuit, naming the input at fault. */
  prove(inputs: ZkKycInputs): ZkKycProof {
    const { circuit, provingKey } = this.keys;
    if (!circuit || !provingKey) throw new Error("proving needs `circuit` (circuit.xbc) and `provingKey` (pk.bin)");
    const leaves = this.wasm.encodeInputs(ZkKyc.schema, toJson(inputs));
    const { proof, publicInputs } = this.wasm.prove(circuit, provingKey, leaves);
    return { proof: proof.slice(), publicInputs: this.decodePublicInputs(publicInputs), publicInputBytes: publicInputs.slice() };
  }

  /** Whether `proof` proves these public inputs. */
  verify(proof: Uint8Array, publicInputs: ZkKycPublicInputs | ZkKycPublicValues | Uint8Array): boolean {
    const { verifyingKey } = this.keys;
    if (!verifyingKey) throw new Error("verifying needs `verifyingKey` (vk.bin)");
    const bytes = publicInputs instanceof Uint8Array ? publicInputs : this.encodePublicInputs(publicInputs);
    try {
      return this.wasm.verify(verifyingKey, proof, bytes);
    } catch {
      return false; // malformed proof bytes
    }
  }

  /** The public inputs as the canonical bytes (`public_inputs.bin`). */
  encodePublicInputs(publicInputs: ZkKycPublicInputs | ZkKycPublicValues): Uint8Array {
    return this.wasm.encodePublicInputs(ZkKyc.schema, toJson(publicInputs));
  }

  /** Canonical public-input bytes, decoded. */
  decodePublicInputs(bytes: Uint8Array): ZkKycPublicValues {
    return decodePublic(JSON.parse(this.wasm.decodePublicValues(ZkKyc.schema, bytes)));
  }
}

function decodePublic(v: any): ZkKycPublicValues {
  return {
    commitment: BigInt(v.commitment),
    bornBefore: new Date(v.bornBefore),
    minNetWorth: BigInt(v.minNetWorth),
    today: new Date(v.today),
    allowed: v.allowed,
  };
}

/** JSON for xark-wasm: `bigint`s as decimal, a `Date` as its UTC day (`YYYY-MM-DD`), bytes as hex. */
function toJson(value: unknown): string {
  return JSON.stringify(value, function (this: any, key: string, v: unknown) {
    const raw = this[key];
    if (raw instanceof Date) {
      if (Number.isNaN(raw.getTime())) throw new TypeError(`${key}: invalid Date`);
      return raw.toISOString().slice(0, 10);
    }
    if (typeof raw === "bigint") return raw.toString();
    if (raw instanceof Uint8Array) return "0x" + Array.from(raw, (b) => b.toString(16).padStart(2, "0")).join("");
    if (raw instanceof Set) return [...raw];
    return v;
  });
}

function fromHex(s: string): Uint8Array {
  const h = s.slice(2);
  return Uint8Array.from({ length: h.length / 2 }, (_, i) => parseInt(h.slice(2 * i, 2 * i + 2), 16));
}
